  3	//! Small, synchronous wrappers for macOS system identity and entropy services.
  4	//!
  5	//! This crate is scoped to the Apple Silicon macOS 13+ target selected by the
  6	//! workspace. It does not provide implementations for other operating systems.
  7	
  8	use std::fmt;
  9	use std::os::fd::BorrowedFd;
 10	
 11	#[allow(unsafe_code)]
 12	mod sys;
 13	
 14	/// Largest request accepted by [`fill_random`].
 15	pub const MAX_RANDOM_BYTES: usize = 256;
 16	
 17	/// Failure reported by a native system service.
 18	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
 19	pub enum SystemError {
 20	    /// The requested random buffer exceeds the wrapper's fixed bound.
 21	    RandomRequestTooLarge { requested: usize, maximum: usize },
 22	    /// `SecRandomCopyBytes` returned a nonzero `OSStatus`.
 23	    RandomStatus(i32),
 24	    /// `getpeereid` failed; this is the `errno` value captured immediately.
 25	    PeerCredentialsErrno(i32),
 26	}
 27	
 28	impl fmt::Display for SystemError {
 29	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 30	        match self {
 31	            Self::RandomRequestTooLarge { requested, maximum } => {
 32	                write!(f, "random request of {requested} bytes exceeds {maximum}")
 33	            }
 34	            Self::RandomStatus(status) => {
 35	                write!(f, "SecRandomCopyBytes failed with OSStatus {status}")
 36	            }
 37	            Self::PeerCredentialsErrno(errno) => {
 38	                write!(f, "getpeereid failed with errno {errno}")
 39	            }
 40	        }
 41	    }
 42	}
 43	
 44	impl std::error::Error for SystemError {}
 45	
 46	/// Fill `output` with bytes from Apple's default cryptographic random source.
 47	///
 48	/// Empty output succeeds without calling the native function. Requests above
 49	/// [`MAX_RANDOM_BYTES`] are rejected before any native call. If the native
 50	/// call fails, every byte in `output` is cleared before its status is returned.
 51	pub fn fill_random(output: &mut [u8]) -> Result<(), SystemError> {
 52	    if output.len() > MAX_RANDOM_BYTES {
 53	        return Err(SystemError::RandomRequestTooLarge {
 54	            requested: output.len(),
 55	            maximum: MAX_RANDOM_BYTES,
 56	        });
 57	    }
 58	    if output.is_empty() {
 59	        return Ok(());
 60	    }
 61	
 62	    let status = sys::fill_random(output);
 63	    random_result(status, output)
 64	}
 65	
 66	fn random_result(status: i32, output: &mut [u8]) -> Result<(), SystemError> {
 67	    if status == 0 {
 68	        Ok(())
 69	    } else {
 70	        output.fill(0);
 71	        Err(SystemError::RandomStatus(status))
 72	    }
 73	}
 74	
 75	/// Return the real user ID of the calling process, as reported by `getuid`.
 76	pub fn current_uid() -> u32 {
 77	    sys::current_uid()
 78	}
 79	
 80	/// Return the user and group IDs associated with a connected peer socket.
 81	///
 82	/// The descriptor is borrowed only for the duration of this call. Credentials
 83	/// are returned as Darwin's 32-bit `uid_t` and `gid_t` values.
 84	pub fn peer_credentials(socket: BorrowedFd<'_>) -> Result<(u32, u32), SystemError> {
 85	    sys::peer_credentials(socket).map_err(SystemError::PeerCredentialsErrno)
 86	}
