  1	//! Narrow ABI boundary for macOS system services.
  2	//!
  3	//! The declarations mirror the local macOS SDK: `SecRandomRef` is an opaque
  4	//! pointer, Darwin `uid_t`/`gid_t` are `u32`, and `getpeereid` accepts `int`.
  5	
  6	use std::ffi::{c_int, c_void};
  7	use std::os::fd::{AsRawFd, BorrowedFd};
  8	
  9	#[link(name = "Security", kind = "framework")]
 10	unsafe extern "C" {
 11	    fn SecRandomCopyBytes(random: *const c_void, count: usize, bytes: *mut c_void) -> c_int;
 12	}
 13	
 14	unsafe extern "C" {
 15	    fn getuid() -> u32;
 16	    fn getpeereid(socket: c_int, uid: *mut u32, gid: *mut u32) -> c_int;
 17	    fn __error() -> *mut c_int;
 18	}
 19	
 20	/// Call Security synchronously with a bounded, exclusively borrowed output.
 21	pub(super) fn fill_random(output: &mut [u8]) -> i32 {
 22	    debug_assert!(!output.is_empty());
 23	    debug_assert!(output.len() <= super::MAX_RANDOM_BYTES);
 24	
 25	    // SAFETY: NULL is Apple's documented default SecRandomRef. The slice
 26	    // pointer is writable for exactly `len()` bytes, `len()` is bounded to 256,
 27	    // and the synchronous API does not retain the pointer, dispatch callbacks,
 28	    // or access it on another thread.
 29	    unsafe {
 30	        SecRandomCopyBytes(
 31	            std::ptr::null(),
 32	            output.len(),
 33	            output.as_mut_ptr().cast::<c_void>(),
 34	        )
 35	    }
 36	}
 37	
 38	/// Read the process real user ID using Darwin's `getuid` ABI.
 39	pub(super) fn current_uid() -> u32 {
 40	    // SAFETY: `getuid` takes no pointers and has no preconditions.
 41	    unsafe { getuid() }
 42	}
 43	
 44	/// Query the credentials tied to the borrowed descriptor and capture errno.
 45	pub(super) fn peer_credentials(socket: BorrowedFd<'_>) -> Result<(u32, u32), i32> {
 46	    let mut uid = 0_u32;
 47	    let mut gid = 0_u32;
 48	    // SAFETY: `socket` keeps a live descriptor borrowed for this call. The
 49	    // output pointers reference initialized local `u32`s matching Darwin's
 50	    // uid_t/gid_t ABI. getpeereid is synchronous, uses the calling thread, and
 51	    // retains neither pointers nor descriptor after returning.
 52	    let result = unsafe { getpeereid(socket.as_raw_fd(), &mut uid, &mut gid) };
 53	    if result == 0 {
 54	        return Ok((uid, gid));
 55	    }
 56	
 57	    // SAFETY: Darwin's `__error` returns this thread's writable errno slot,
 58	    // which is valid to read immediately after a failed system call.
 59	    let errno = unsafe { *__error() };
 60	    Err(errno)
 61	}
