 23	fn maximum_random_request_is_accepted() {
 24	    let mut bytes = [0xA5; MAX_RANDOM_BYTES];
 25	
 26	    assert_eq!(fill_random(&mut bytes), Ok(()));
 27	    assert_ne!(bytes, [0xA5; MAX_RANDOM_BYTES]);
