 30	#[test]
 31	fn random_request_over_the_limit_is_rejected_without_changing_output() {
 32	    let mut bytes = [0xA5; MAX_RANDOM_BYTES + 1];
 33	
 34	    assert_eq!(
 35	        fill_random(&mut bytes),
 36	        Err(SystemError::RandomRequestTooLarge {
 37	            requested: MAX_RANDOM_BYTES + 1,
 38	            maximum: MAX_RANDOM_BYTES,
 39	        })
 40	    );
 41	    assert_eq!(bytes, [0xA5; MAX_RANDOM_BYTES + 1]);
 42	}
