 45	fn connected_unix_socket_reports_the_current_user() {
 46	    let (left, _right) = UnixStream::pair().expect("create local socket pair");
 47	
 48	    let (peer_uid, _peer_gid) = peer_credentials(left.as_fd()).expect("read peer credentials");
 49	    assert_eq!(peer_uid, current_uid());
 50	}
